Current workaround is to define your own builder via API:

```js
const Bundler = require('parcel-bundler');
const Path = require('path');

const entryFiles = [
  Path.join(__dirname, 'js/index.ts'),
  Path.join(__dirname, './css/main.css')
];

const options = {
  outDir: '../priv/static',
  watch: true,
  cache: true,
  contentHash: false,
  scopeHoist: true,
  hmr: false,
  sourceMaps: true,
  detailedReport: true
};

// Exit process when stdin closes
process.stdin.on('end', () => {
  console.info('\nStdin ended, exiting\n');
  process.exit(0)
});
process.stdin.resume();

(async function() {
  const bundler = new Bundler(entryFiles, options);

  const bundle = await bundler.bundle();
})();
```
